using System;using System.IO;using System.Linq;using System.Collections;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.UI;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {
 public sealed class DesignReviewTests {
  GameRuntime game;string directory;
  [UnitySetUp]public IEnumerator Setup(){directory=Path.Combine(Path.GetTempPath(),"idle-design-"+Guid.NewGuid());Directory.CreateDirectory(directory);GameRuntime.SavePathOverride=Path.Combine(directory,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();game.Act(s=>NarrativeBridge.Action(s,"name","AURA"));for(int i=0;i<5;i++)game.Act(s=>NarrativeBridge.Action(s,"continue"));game.Act(s=>NarrativeBridge.Action(s,"skip-tutorial"));game.Show("hardware");yield return null;}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;}
  [UnityTest]public IEnumerator CaptureBaselineAndProveEditorAccess(){string output=game.GetComponent<MobileShell>()==null?"/tmp/idle-design-before":"/tmp/idle-design-after";Directory.CreateDirectory(output);foreach(int width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/labor-"+width+".png");yield return null;}File.WriteAllLines(output+"/scene-hierarchy.txt",UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None).Select(t=>t.name));Assert.That(game.State.Hardware[0],Is.Zero);Assert.That(game.Act(s=>Game.Buy(s,"calculator",1)),Is.True);Assert.That(game.State.Hardware[0],Is.EqualTo(1));Debug.Log("DESIGN_CAPABILITY_PROOF scene=IdleIntelligence PlayMode=running console=readable captures=320,390,430 realPurchase=passed isolatedSave="+game.SavePath);}
  [UnityTest]public IEnumerator ReviewMobileSection(){
   string output="/tmp/idle-design-review";Directory.CreateDirectory(output);game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Story.seen=NarrativeCatalog.Dialogues.Select(d=>d.Id).ToArray();n.Story.enabled=false;n.Credits=ScientificNumber.From(50000);n.Workshop.inventory=ItemBalance.Items.Take(6).Select((d,i)=>new ItemInstance{id="design-"+i,type=d.Id,rarity=i,level=12}).ToArray();return n;});yield return null;
   foreach(string language in new[]{"de","en"}){game.Act(s=>{var n=s.Copy();n.Settings.language=language;return n;});game.Show("hardware");yield return new WaitForSecondsRealtime(.45f);foreach(int width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/labor-"+language+"-"+width+".png");yield return null;}
    game.Show("items");yield return null;game.WorkshopView.ChangeMode("inventory");yield return new WaitForSecondsRealtime(.45f);foreach(int width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/items-"+language+"-"+width+".png");yield return new WaitForSecondsRealtime(.45f);}
    Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(6));game.WorkshopView.OpenItem("design-1");yield return new WaitForSecondsRealtime(.45f);foreach(int width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/detail-"+language+"-"+width+".png");yield return new WaitForSecondsRealtime(.45f);}
    Assert.That(game.WorkshopView.DetailRoot.transform.Find("DetailPanel").GetComponent<CanvasGroup>().alpha,Is.EqualTo(1));Assert.That(game.WorkshopView.DetailPortrait.Frame.color,Is.EqualTo(ItemPortrait.RarityColor(1)));game.WorkshopView.CloseDetail();game.Show("hardware");yield return null;
   }
   game.HardwareTab.onClick.Invoke();yield return null;Assert.That(game.CurrentTab,Is.EqualTo("hardware"));game.GetComponent<MobileShell>().Laboratory.Train.onClick.Invoke();yield return null;Assert.That(game.CurrentTab,Is.EqualTo("training"));game.Show("hardware");yield return null;
   game.Show("items");yield return null;game.WorkshopView.ChangeMode("inventory");game.WorkshopView.OpenItem("design-0");yield return new WaitForSecondsRealtime(.45f);var equip=game.WorkshopView.DetailActions.GetComponentsInChildren<Button>().First(b=>b.name.StartsWith("equip-"));Assert.That(equip.interactable,Is.True);equip.onClick.Invoke();Assert.That(game.State.Workshop.equipped.Contains("design-0"),Is.True);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Workshop.equipped.Contains("design-0"),Is.True);game.Show("items");yield return null;game.WorkshopView.ChangeMode("inventory");yield return new WaitForSecondsRealtime(.45f);WorkshopTests.Capture(390,844,output+"/equipped-reloaded.png");
   var read=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(read.Writable,Is.True);Assert.That(read.State.Workshop.inventory.Length,Is.EqualTo(6));Assert.That(read.State.Legacy.prepared,Is.True);
  }
  [UnityTest]public IEnumerator RecordRealTapAndOverdrive(){string output="/tmp/idle-design-motion";Directory.CreateDirectory(output);game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Story.seen=NarrativeCatalog.Dialogues.Select(d=>d.Id).ToArray();n.Story.enabled=false;n.Hardware[0]=10;n.Charge=96;n.Workshop.inventory=new[]{new ItemInstance{id="record-module",type="quantum-diagnostic-module",rarity=1,level=12}};n.Data=ScientificNumber.From(170);return n;});game.Show("hardware");yield return null;var times=new System.Collections.Generic.List<float>();for(int i=0;i<200;i++){times.Add(Time.realtimeSinceStartup);if(i==8||i==24||i==40||i==56)PointerTap(new Vector2((i%3-1)*45,10));if(i==88)Press(GameObject.Find("hardware-calculator").GetComponentsInChildren<Button>().First(b=>b.name=="HardwarePurchase"),true);if(i==92)Press(GameObject.Find("hardware-calculator").GetComponentsInChildren<Button>().First(b=>b.name=="HardwarePurchase"),false);if(i==100){game.ItemsTab.onClick.Invoke();game.WorkshopView.ChangeMode("inventory");}if(i==112)game.WorkshopView.OpenItem("record-module");if(i==140)Press(GameObject.Find("equip-research").GetComponent<Button>(),true);if(i==144){Press(GameObject.Find("equip-research").GetComponent<Button>(),false);Assert.That(game.State.Workshop.equipped[2],Is.EqualTo("record-module"));}if(i==164)game.WorkshopView.OpenItem("record-module");if(i==190)game.WorkshopView.CloseDetail();WorkshopTests.Capture(390,844,output+"/"+i.ToString("D4")+".png");yield return new WaitForSecondsRealtime(.05f);}File.WriteAllLines(output+"/times.txt",times.Select(t=>t.ToString("R",System.Globalization.CultureInfo.InvariantCulture)));Assert.That(game.State.Lifetime.taps,Is.EqualTo(4),"Three ordinary taps and one activation; animation never grants taps");Assert.That(game.State.Overdrives,Is.EqualTo(1));Assert.That(game.State.ActiveUntil,Is.GreaterThan(0));Assert.That(game.State.Hardware[0],Is.EqualTo(11));Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(1));Assert.That(game.State.Workshop.equipped[2],Is.EqualTo("record-module"));game.Show("hardware");yield return null;game.Act(s=>{var n=s.Copy();n.Workshop.reducedMotion=true;n.Settings.effects=false;return n;});yield return null;Assert.That(game.GetComponent<MobileShell>().Laboratory.Art.localScale,Is.EqualTo(Vector3.one*1.08f));WorkshopTests.Capture(390,844,output+"/reduced.png");}
  void Press(Button button,bool down){var e=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){button=UnityEngine.EventSystems.PointerEventData.InputButton.Left};if(down)UnityEngine.EventSystems.ExecuteEvents.Execute(button.gameObject,e,UnityEngine.EventSystems.ExecuteEvents.pointerDownHandler);else{UnityEngine.EventSystems.ExecuteEvents.Execute(button.gameObject,e,UnityEngine.EventSystems.ExecuteEvents.pointerUpHandler);UnityEngine.EventSystems.ExecuteEvents.Execute(button.gameObject,e,UnityEngine.EventSystems.ExecuteEvents.pointerClickHandler);}}
  void PointerTap(Vector2 local){var stage=(RectTransform)game.TapButton.transform.parent;var screen=RectTransformUtility.WorldToScreenPoint(null,stage.TransformPoint(local));var e=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){position=screen,pressPosition=screen,button=UnityEngine.EventSystems.PointerEventData.InputButton.Left};UnityEngine.EventSystems.ExecuteEvents.Execute(game.TapButton.gameObject,e,UnityEngine.EventSystems.ExecuteEvents.pointerDownHandler);UnityEngine.EventSystems.ExecuteEvents.Execute(game.TapButton.gameObject,e,UnityEngine.EventSystems.ExecuteEvents.pointerUpHandler);UnityEngine.EventSystems.ExecuteEvents.Execute(game.TapButton.gameObject,e,UnityEngine.EventSystems.ExecuteEvents.pointerClickHandler);}
  [UnityTest]public IEnumerator UnifiedSlotsLongNamesAndUsefulComparison(){
   string output="/tmp/idle-design2-review";Directory.CreateDirectory(output);game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Story.enabled=false;n.Story.seen=NarrativeCatalog.Dialogues.Select(x=>x.Id).ToArray();n.Hardware[0]=10;n.Credits=ScientificNumber.From(50000);var longest=ItemBalance.Items.OrderByDescending(d=>SettingsRules.Text("de","item:"+d.Id).Length).First();n.Workshop.inventory=new[]{new ItemInstance{id="strong",type="quantum-chip",rarity=5,level=60},new ItemInstance{id="weak",type="quantum-chip",rarity=0,level=1},new ItemInstance{id="long",type=longest.Id,rarity=1,level=12}};return n;});
   foreach(string language in new[]{"de","en"}){game.Act(s=>SettingsRules.Change(s,"language",language));game.Show("items");yield return null;game.WorkshopView.ChangeMode("inventory");yield return new WaitForSecondsRealtime(.45f);
    foreach(int width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/empty-"+language+"-"+width+".png");yield return null;}
    GameObject.Find("equipment-processorAux").GetComponent<ItemPortrait>().Button.onClick.Invoke();yield return new WaitForSecondsRealtime(.45f);Assert.That(game.WorkshopView.DetailText.text,Does.Not.Contain("W01"));foreach(int width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/locked-"+language+"-"+width+".png");yield return null;}game.WorkshopView.CloseDetail();
    game.WorkshopView.OpenItem("long");yield return new WaitForSecondsRealtime(.45f);foreach(int width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/long-"+language+"-"+width+".png");yield return null;}game.WorkshopView.CloseDetail();
   }
   Assert.That(game.Act(s=>Workshop.Equip(s,"strong")),Is.True);game.Show("items");yield return null;game.WorkshopView.ChangeMode("inventory");yield return null;
   var equipment=GameObject.Find("equipment-processor").GetComponent<ItemPortrait>();var inventory=GameObject.Find("item-strong").GetComponentInChildren<ItemPortrait>();Assert.That(equipment.Frame.Shape,Is.EqualTo(inventory.Frame.Shape));equipment.Bind(equipment.Item,"universal1");Assert.That(equipment.Frame.Shape,Is.EqualTo(inventory.Frame.Shape),"Occupied universal slots retain the actual item shape");Assert.That(equipment.Frame.color,Is.EqualTo(inventory.Frame.color));Assert.That(equipment.Art.rectTransform.sizeDelta,Is.EqualTo(inventory.Art.rectTransform.sizeDelta));
   game.WorkshopView.OpenItem("weak");yield return new WaitForSecondsRealtime(.45f);Assert.That(game.WorkshopView.DetailText.text,Does.Not.Contain("0 → 0"));Assert.That(game.WorkshopView.DetailActions.GetComponentsInChildren<Button>().First(b=>b.name.StartsWith("equip-")).GetComponentInChildren<Text>().color,Is.EqualTo(GameTheme.Background));Assert.That(game.WorkshopView.DetailText.text,Does.Contain("#FF929B"),"Replacing a stronger processor retains a visible drawback");WorkshopTests.Capture(390,844,output+"/drawback-en.png");game.WorkshopView.CloseDetail();
   foreach(string language in new[]{"de","en"}){game.Act(s=>SettingsRules.Change(s,"language",language));game.WorkshopView.ChangeMode("inventory");yield return null;foreach(int width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/equipped-"+language+"-"+width+".png");yield return null;}}
   game.Show("hardware");yield return new WaitForSecondsRealtime(.25f);double taps=game.State.Lifetime.taps;PointerTap(new Vector2(40,20));Assert.That(game.State.Lifetime.taps,Is.EqualTo(taps+1));Assert.That(game.GetComponent<MobileShell>().Laboratory.Floating.rectTransform.anchoredPosition.x,Is.EqualTo(40).Within(1));
   game.Show("settings");yield return null;var save=GameObject.Find("ManualSave").GetComponent<Button>();Assert.That(save.interactable,Is.True);save.onClick.Invoke();var loaded=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(loaded.Writable,Is.True);Assert.That(loaded.State.Workshop.equipped.Contains("strong"),Is.True);
  }
  [UnityTest]public IEnumerator InterruptAndReducedMotionPreserveCommittedEquipment(){game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Story.enabled=false;n.Story.seen=NarrativeCatalog.Dialogues.Select(x=>x.Id).ToArray();n.Workshop.inventory=new[]{new ItemInstance{id="interrupt",type="quantum-chip",rarity=1,level=1}};return n;});game.Show("items");yield return null;game.WorkshopView.ChangeMode("inventory");var credits=game.State.Credits;game.WorkshopView.OpenItem("interrupt");var equip=game.WorkshopView.DetailActions.GetComponentsInChildren<Button>().First(b=>b.name.StartsWith("equip-"));equip.onClick.Invoke();Assert.That(game.State.Workshop.equipped.Contains("interrupt"),Is.True);game.HardwareTab.onClick.Invoke();yield return new WaitForSecondsRealtime(.4f);Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(1));Assert.That(game.State.Credits.CompareTo(credits),Is.Zero);game.Act(s=>SettingsRules.Change(s,"toggle-effects"));game.Show("items");yield return null;game.WorkshopView.ChangeMode("inventory");game.WorkshopView.OpenItem("interrupt");Assert.That(game.WorkshopView.DetailPortrait.transform.localScale,Is.EqualTo(Vector3.one));Assert.That(game.WorkshopView.DetailPortrait.GetComponentsInChildren<Transform>().Any(t=>t.name=="RevealPixel"),Is.False);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(1));Assert.That(game.State.Workshop.equipped.Contains("interrupt"),Is.True);Assert.That(game.State.Settings.effects,Is.False);game.Show("items");yield return null;game.WorkshopView.ChangeMode("blueprints");game.WorkshopView.Info.onClick.Invoke();string expected=WorkshopUI.Costs(Workshop.Quote(game.State,ItemBalance.Items[0].Id));Assert.That(game.WorkshopView.DetailText.text,Does.Contain(expected),"Recipe preview retains its complete cost line");}
  public static void CheckItemTouchTargets(Camera camera){foreach(var b in UnityEngine.Object.FindObjectsByType<Button>(FindObjectsSortMode.None).Where(b=>b.name.StartsWith("equipment-")||b.name.StartsWith("equip-")||b.name=="Upgrade"||b.name=="MoreItemActionsToggle"||b.name=="Save")){var r=b.GetComponent<RectTransform>();var c=new Vector3[4];r.GetWorldCorners(c);var a=RectTransformUtility.WorldToScreenPoint(camera,c[0]);var z=RectTransformUtility.WorldToScreenPoint(camera,c[2]);Assert.That(z.x-a.x,Is.GreaterThanOrEqualTo(43.5f),b.name+" touch width");Assert.That(z.y-a.y,Is.GreaterThanOrEqualTo(43.5f),b.name+" touch height");}}
  public static void CheckGeometry(int width,int height,Camera camera,string path){Assert.That(GameObject.Find("LaboratoryStage").GetComponent<LayoutElement>().preferredHeight,Is.EqualTo((float)height/width<1.9f?180:240),"Responsive stage uses the actual current viewport");var price=GameObject.Find("hardware-calculator").transform.Find("PurchaseCost/HardwarePrice");var a=new Vector3[4];var b=new Vector3[4];price.Find("CreditIcon").GetComponent<RectTransform>().GetWorldCorners(a);price.Find("CostAmount").GetComponent<RectTransform>().GetWorldCorners(b);Assert.That(a[2].x,Is.LessThanOrEqualTo(b[0].x+.1f),"Coin and long price occupy separate layout cells");var names=new[]{"HardwareTab","ResearchTab","ItemsTab","ShopTab","Menu"}.Concat(GameObject.Find("PrestigeTab")==null?Array.Empty<string>():new[]{"PrestigeTab"});var measurements=new System.Collections.Generic.List<string>();foreach(var name in names){var rect=GameObject.Find(name).GetComponent<RectTransform>();var corners=new Vector3[4];rect.GetWorldCorners(corners);var min=RectTransformUtility.WorldToScreenPoint(camera,corners[0]);var max=RectTransformUtility.WorldToScreenPoint(camera,corners[2]);Assert.That(max.y-min.y,Is.GreaterThanOrEqualTo(43.5f),name+" actual pixel touch height at "+width);Assert.That(min.x,Is.GreaterThanOrEqualTo(-.5f),name);Assert.That(max.x,Is.LessThanOrEqualTo(width+.5f),name);Assert.That(min.y,Is.GreaterThanOrEqualTo(-.5f),name);Assert.That(max.y,Is.LessThanOrEqualTo(height+.5f),name);measurements.Add(name+" "+min+" "+max);}File.WriteAllLines(path+".geometry.txt",measurements);}
 }
